public class PedidoTools {

    @Tool("Busca um pedido pelo ID")
    public Pedido buscarPedido(String pedidoId) {
        return pedidoService.buscarPorId(pedidoId);
    }

    @Tool("Cancela um pedido se ainda estiver pendente")
    public CancelamentoResponse cancelarPedido(String pedidoId) {
        return pedidoService.cancelar(pedidoId);
    }
}

@Tool("Consulta status de um serviço")
public ServiceStatus getServiceStatus(String serviceName) {
    return observabilityClient.getStatus(serviceName);
}

@Tool("Lista últimos deploys de um serviço")
public List<Deployment> getDeployments(String serviceName) {
    return deploymentClient.lastDeployments(serviceName);
}

@Tool("Busca erros recentes nos logs")
public List<LogEvent> searchRecentErrors(String serviceName) {
    return logClient.searchErrors(serviceName);
}

